  public boolean onTouchEvent(MotionEvent e){int a=e.getActionMasked(),i=e.getActionIndex(),id=e.getPointerId(i);float x=e.getX(i),y=e.getY(i),ww=getWidth(),hh=getHeight();if(a==0||a==5){if(x>ww-d(80)&&y<d(72)){w.nextArea();invalidate();return true;}if(x<ww*.42f&&y>hh-d(165)){joy=id;move(x,y);return true;}if(x>ww-d(130)&&y>hh-d(135)){w.jump();return true;}if(x>ww-d(210)&&x<ww-d(115)&&y>hh-d(100)){w.use();invalidate();return true;}if(x>ww-d(100)&&y>hh-d(225)&&y<hh-d(115)){w.turn(.5f);return true;}look=id;lastX=x;return true;}if(a==2){for(int k=0;k<e.getPointerCount();k++){int q=e.getPointerId(k);float xx=e.getX(k),yy=e.getY(k);if(q==joy)move(xx,yy);if(q==look){w.turn((xx-lastX)*.008f);lastX=xx;}}return true;}if(a==1||a==6||a==3){if(id==joy){joy=-1;w.move(0,0);invalidate();}if(id==look)look=-1;return true;}return true;}
